    names = await readdir(dir)
  } catch {
    return
  }
  const ownDomain = await deps.ownPidDomain()
  await Promise.all(
    names.map(async name => {
      const match = INBOX_KEY_TEMP_FILE.exec(name)
      if (!match || !deps.isProcessGone(Number.parseInt(match[1]!, 10))) return
